        val width = ceil(box.widthPx).toInt() + 2 * MARGIN
        val height = ceil(box.ascentPx + box.depthPx).toInt() + 2 * MARGIN
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
