        return maxOf(
            0f,
            MARGIN - top.toFloat(),
            MARGIN - left.toFloat(),
            right + 1 - (MARGIN + box.widthPx),
            bottom + 1 - (MARGIN + box.ascentPx + box.depthPx),
        )
    }

    private companion object {
        const val SIZE_PX = 50f
        const val BLACK = 0xFF000000.toInt()
        const val MARGIN = 16
        const val INK_ALPHA = 0x40
        const val MAX_OVERFLOW_PX = 1f
    }
