                val page = PDPage(PDRectangle.A4)
                document.addPage(page)
                PDPageContentStream(document, page).use {
                    it.addRect(50f + index * 10f, 50f, 100f, 100f)
                    it.fill()
                }
            }
            document.save(file)
        }
        return file
    }
}

