package dev.folio.app.spikes

import android.annotation.SuppressLint
import android.app.Activity
import android.content.Context
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Matrix
import android.os.SystemClock
import android.view.Choreographer
import android.view.MotionEvent
import android.view.View
import android.widget.FrameLayout
import androidx.annotation.MainThread
import androidx.ink.authoring.InProgressStrokeId
import androidx.ink.authoring.InProgressStrokesFinishedListener
import androidx.ink.authoring.InProgressStrokesView
import androidx.ink.brush.Brush
import androidx.ink.brush.StockBrushes
import androidx.ink.rendering.android.canvas.CanvasStrokeRenderer
import androidx.ink.strokes.Stroke
import dev.folio.core.common.PerfMonitor
import dev.folio.core.render.DisplayModeHelper

/** When finished wet strokes are removed from [InProgressStrokesView] (P01-S1). */
internal enum class Handoff {
    /** In `onStrokesFinished`, right after invalidating the committed layer (androidx.ink sample). */
    IMMEDIATE,

    /** In the next Choreographer frame callback (05-canvas-rendering.md#dry-handoff step 3). */
    FRAME,

    /** After the frame that draws the committed stroke was submitted (ViewTreeObserver frame commit). */
    COMMIT,
    ;

    companion object {
        fun parse(name: String): Handoff? = entries.firstOrNull { it.name.equals(name, ignoreCase = true) }
    }
}

/**
 * Spike P01-S1: a white page drawing committed strokes with [CanvasStrokeRenderer] under an
 * [InProgressStrokesView] fed by stylus events, with the highest refresh mode requested.
 * Deleted or promoted by P01-T08.
 */
@SuppressLint("ViewConstructor") // created in code by AppDebugHooks only
@MainThread
internal class SpikeInkView(
    activity: Activity,
) : FrameLayout(activity),
    InProgressStrokesFinishedListener {
    private val committed = CommittedStrokesView(activity)
    private val wet = InProgressStrokesView(activity)
    private val displayModes = DisplayModeHelper(activity.window)
    private val brush = Brush.createWithColorIntArgb(StockBrushes.pressurePen(), INK_ARGB, BRUSH_SIZE_PX, BRUSH_EPSILON)
    private var strokeId: InProgressStrokeId? = null
    private var pointerId = NO_POINTER

    var handoff = Handoff.COMMIT
    var requestedHz: Float? = null
        private set
    val committedCount: Int get() = committed.strokes.size
    var pendingWetCount = 0
        private set

    init {
        addView(committed, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))
        addView(wet, LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.MATCH_PARENT))
        wet.addFinishedStrokesListener(this)
    }

    override fun onAttachedToWindow() {
        super.onAttachedToWindow()
        requestedHz = display?.let(displayModes::request)
    }

    override fun onDetachedFromWindow() {
        displayModes.release()
        super.onDetachedFromWindow()
    }

    /** Active refresh rate of the display showing this view. */
    fun activeHz(): Float? = display?.refreshRate

    fun clear() {
        committed.strokes.clear()
        committed.invalidate()
    }

    override fun dispatchTouchEvent(event: MotionEvent): Boolean = PerfMonitor.trace(SECTION_TOUCH) { handleTouch(event) }

    // HOT PATH: runs per MotionEvent; no allocation, no logging.
    private fun handleTouch(event: MotionEvent): Boolean {
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                if (event.getToolType(0) != MotionEvent.TOOL_TYPE_STYLUS) return true // fingers never draw
                requestUnbufferedDispatch(event)
                pointerId = event.getPointerId(0)
                strokeId = wet.startStroke(event, pointerId, brush)
            }

            MotionEvent.ACTION_MOVE -> {
                strokeId?.let { wet.addToStroke(event, pointerId, it) }
            }

            MotionEvent.ACTION_UP -> {
                val id = strokeId ?: return true
                if (event.flags and MotionEvent.FLAG_CANCELED != 0) wet.cancelStroke(id, event) else wet.finishStroke(event, pointerId, id)
                strokeId = null
                pointerId = NO_POINTER
            }

            MotionEvent.ACTION_CANCEL -> {
                strokeId?.let { wet.cancelStroke(it, event) }
                strokeId = null
                pointerId = NO_POINTER
            }
        }
        return true
    }

    override fun onStrokesFinished(strokes: Map<InProgressStrokeId, Stroke>) {
        val finishedNs = SystemClock.elapsedRealtimeNanos()
        committed.strokes.addAll(strokes.values)
        committed.invalidate()
        pendingWetCount += strokes.size
        val remove = {
            wet.removeFinishedStrokes(strokes.keys)
            pendingWetCount -= strokes.size
            PerfMonitor.record(SECTION_HANDOFF, SystemClock.elapsedRealtimeNanos() - finishedNs)
        }
        when (handoff) {
            Handoff.IMMEDIATE -> remove()
            Handoff.FRAME -> Choreographer.getInstance().postFrameCallback { remove() }
            Handoff.COMMIT -> committed.viewTreeObserver.registerFrameCommitCallback(remove)
        }
    }

    /** The committed-content layer: paper plus every finished stroke, redrawn in full (spike only). */
    private class CommittedStrokesView(
        context: Context,
    ) : View(context) {
        val strokes = ArrayList<Stroke>()
        private val renderer = CanvasStrokeRenderer.create()
        private val identity = Matrix()

        override fun onDraw(canvas: Canvas) {
            canvas.drawColor(Color.WHITE)
            for (stroke in strokes) renderer.draw(canvas, stroke, identity)
        }
    }

    companion object {
        const val ROUTE = "spike-ink"
        const val SECTION_TOUCH = "ink:onTouch"
        const val SECTION_HANDOFF = "ink:handoff"
        private const val INK_ARGB = 0xFF1A1A1A.toInt()
        private const val BRUSH_SIZE_PX = 6f
        private const val BRUSH_EPSILON = 0.1f
        private const val NO_POINTER = -1
    }
}

package dev.folio.app.spikes

import android.annotation.SuppressLint
import android.content.Context
import android.graphics.Canvas
import android.graphics.Paint
import android.os.Environment
import android.view.InputDevice
import android.view.KeyEvent
import android.view.MotionEvent
import android.view.View
import androidx.annotation.MainThread
import dev.folio.app.BuildConfig
import dev.folio.core.common.FolioDispatchers
import dev.folio.core.common.FolioLog
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import java.io.File
import java.io.IOException

/**
 * Spike P01-S7: live readout of what the Focus Pen delivers (tool type, pressure, tilt,
 * orientation, distance, hover, buttons, keys, batch sizes, sample rate) plus the stylus
 * InputDevice motion ranges; writes `Folio-Debug/probe/stylus.json` every second while it changes.
 * Deleted or promoted by P01-T08.
 */
@SuppressLint("ViewConstructor") // created in code by AppDebugHooks only
@MainThread
internal class SpikeStylusView(
    context: Context,
    private val dispatchers: FolioDispatchers,
) : View(context) {
    private val scope = CoroutineScope(SupervisorJob() + dispatchers.main)
    private val output = File(File(Environment.getExternalStorageDirectory(), BuildConfig.LIBRARY_ROOT), "probe/stylus.json")
    private val text = Paint(Paint.ANTI_ALIAS_FLAG).apply { textSize = TEXT_PX }
    private val dot = Paint(Paint.ANTI_ALIAS_FLAG)
    private var stats = StylusStats()
    private var dirty = true
    private var lastX = -1f
    private var lastY = -1f
    private var lastPressure = 0f
    private var lastLine = ""

    /** Last write error, or null. */
    var writeError: String? = null
        private set

    init {
        isFocusable = true
        isFocusableInTouchMode = true
        setBackgroundColor(BACKGROUND_ARGB)
    }

    override fun onAttachedToWindow() {
        super.onAttachedToWindow()
        requestFocus()
        scope.launch {
            while (isActive) {
                if (dirty) write(snapshot())
                delay(WRITE_INTERVAL_MS)
            }
        }
    }

    override fun onDetachedFromWindow() {
        scope.cancel()
        super.onDetachedFromWindow()
    }

    /** Clears all counters. */
    fun reset() {
        stats = StylusStats()
        dirty = true
        invalidate()
    }

    /** Devices with stylus sources and their motion ranges, plus the accumulated stats. */
    fun snapshot(): JsonObject =
        buildJsonObject {
            put("stats", stats.toJson())
            put("devices", stylusDevices())
            put("writeError", writeError)
        }

    @SuppressLint("ClickableViewAccessibility") // probe surface, no click action
    override fun onTouchEvent(event: MotionEvent): Boolean {
        record(event, hovering = false)
        when (event.actionMasked) {
            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> stats.onGestureEnd()
            MotionEvent.ACTION_BUTTON_PRESS -> stats.onButtonPress(event.actionButton)
        }
        return true
    }

    override fun onHoverEvent(event: MotionEvent): Boolean {
        record(event, hovering = true)
        return true
    }

    override fun onGenericMotionEvent(event: MotionEvent): Boolean {
        if (event.actionMasked == MotionEvent.ACTION_BUTTON_PRESS) stats.onButtonPress(event.actionButton)
        record(
            event,
            hovering =
                event.actionMasked != MotionEvent.ACTION_BUTTON_PRESS && event.actionMasked != MotionEvent.ACTION_BUTTON_RELEASE,
        )
        return true
    }

    /** Records every key that reaches the app (pen buttons might arrive as keys); BACK still navigates. */
    override fun dispatchKeyEvent(event: KeyEvent): Boolean {
        if (event.keyCode == KeyEvent.KEYCODE_BACK) return super.dispatchKeyEvent(event)
        if (event.action == KeyEvent.ACTION_DOWN) {
            stats.onKey(event.keyCode)
            lastLine = "key ${KeyEvent.keyCodeToString(event.keyCode)} source=0x${event.source.toString(HEX)}"
            dirty = true
            invalidate()
        }
        return true
    }

    override fun onDraw(canvas: Canvas) {
        var y = TEXT_PX * 2
        val lines = listOf(lastLine) + stats.toJson().entries.map { (key, value) -> "$key: $value" }
        for (line in lines) {
            canvas.drawText(line, TEXT_PX, y, text)
            y += TEXT_PX * LINE_SPACING
        }
        writeError?.let { canvas.drawText("write error: $it", TEXT_PX, y, text) }
        if (lastX >= 0f) {
            dot.alpha = (OPAQUE * lastPressure.coerceIn(MIN_DOT_ALPHA, 1f)).toInt()
            canvas.drawCircle(lastX, lastY, DOT_RADIUS_PX, dot)
        }
    }

    private fun record(
        event: MotionEvent,
        hovering: Boolean,
    ) {
        val pointer = event.actionIndex
        val toolType = event.getToolType(pointer)
        stats.onBatch(event.historySize)
        if (!hovering) {
            for (h in 0 until event.historySize) stats.onSampleTime(event.getHistoricalEventTimeNanos(h))
            stats.onSampleTime(event.eventTimeNanos)
        }
        stats.onSample(
            toolType = toolType,
            hovering = hovering,
            pressure = event.getPressure(pointer),
            tiltRad = event.getAxisValue(MotionEvent.AXIS_TILT, pointer),
            orientationRad = event.getOrientation(pointer),
            distance = event.getAxisValue(MotionEvent.AXIS_DISTANCE, pointer),
            buttonState = event.buttonState,
        )
        lastX = event.getX(pointer)
        lastY = event.getY(pointer)
        lastPressure = event.getPressure(pointer)
        lastLine =
            "${MotionEvent.actionToString(event.actionMasked)} tool=$toolType p=%.3f tilt=%.2f orient=%.2f dist=%.2f buttons=%d hist=%d"
                .format(
                    lastPressure,
                    event.getAxisValue(MotionEvent.AXIS_TILT, pointer),
                    event.getOrientation(pointer),
                    event.getAxisValue(MotionEvent.AXIS_DISTANCE, pointer),
                    event.buttonState,
                    event.historySize,
                )
        dirty = true
        invalidate()
    }

    private fun stylusDevices() =
        buildJsonArray {
            for (id in InputDevice.getDeviceIds()) {
                val device = InputDevice.getDevice(id) ?: continue
                if (!device.supportsSource(InputDevice.SOURCE_STYLUS)) continue
                add(
                    buildJsonObject {
                        put("name", device.name)
                        put("sources", "0x" + device.sources.toString(HEX))
                        put(
                            "ranges",
                            buildJsonArray {
                                for (range in device.motionRanges) {
                                    add(
                                        buildJsonObject {
                                            put("axis", MotionEvent.axisToString(range.axis))
                                            put("source", "0x" + range.source.toString(HEX))
                                            put("min", range.min)
                                            put("max", range.max)
                                            put("resolution", range.resolution)
                                            put("fuzz", range.fuzz)
                                        },
                                    )
                                }
                            },
                        )
                    },
                )
            }
        }

    private suspend fun write(json: JsonObject) {
        dirty = false
        writeError =
            withContext(dispatchers.io) {
                try {
                    output.parentFile?.mkdirs()
                    val tmp = File(output.parentFile, output.name + ".tmp")
                    tmp.writeText(json.toString())
                    if (!tmp.renameTo(output)) throw IOException("rename to ${output.name} failed")
                    null
                } catch (e: IOException) {
                    FolioLog.w(TAG, "probe write failed", e)
                    e.message
                }
            }
    }

    companion object {
        const val ROUTE = "spike-stylus"
        private const val TAG = "SpikeStylus"
        private const val TEXT_PX = 30f
        private const val LINE_SPACING = 1.4f
        private const val DOT_RADIUS_PX = 24f
        private const val OPAQUE = 255
        private const val MIN_DOT_ALPHA = 0.15f
        private const val WRITE_INTERVAL_MS = 1_000L
        private const val HEX = 16
        private const val BACKGROUND_ARGB = 0xFFFFFFFF.toInt()
    }
}

