import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/**
 * Spike P01-S3: every bundled font on college-ruled paper (U = 7.1 mm, body M), laid out with the
 * selected [BaselineMethod]. Finger drag pans; zoom and method come from `debugcmd.sh spike-fonts`.
 * Deleted or promoted by P01-T08.
 */
@SuppressLint("ViewConstructor") // created in code by AppDebugHooks only
@MainThread
internal class SpikeFontsView(
    context: Context,
    private val dispatchers: FolioDispatchers,
) : View(context) {
    private val scope = CoroutineScope(SupervisorJob() + dispatchers.main)
    private val resolver = createFontFamilyResolver(context)
    private val layouter = GridTextLayouter(resolver, FontMetricsCache(resolver))
    private val sidePaddingPx = SIDE_PADDING_DP * resources.displayMetrics.density
    private var specimen: FontSpecimen? = null
    private var build: Job? = null
    private var offsetXPx = 0f
    private var offsetYPx = 0f
    private var lastX = 0f
    private var lastY = 0f

    var method = BaselineMethod.GRID_PITCH
        private set

    /** Zoom as a multiple of fit-width. */
    var zoom = 1f
        private set

    /** Time to lay out all specimen blocks, null while building. */
    var layoutMs: Double? = null
        private set

    /** px per pt at the current zoom. */
    val scale: Float get() = (width - 2 * sidePaddingPx) / FontSpecimen.WIDTH_PT * zoom

    override fun onAttachedToWindow() {
        super.onAttachedToWindow()
        rebuild()
    }

    override fun onDetachedFromWindow() {
        scope.cancel()
        super.onDetachedFromWindow()
    }

    /** Lays out the specimen again with [next]. */
    fun switchMethod(next: BaselineMethod) {
        method = next
        rebuild()
    }

    /** Sets [target] zoom keeping the view center fixed. */
    fun applyZoom(target: Float) {
        val before = scale
        val focusX = width / 2f
        val focusY = height / 2f
        zoom = target.coerceIn(MIN_ZOOM, MAX_ZOOM)
        val k = if (before == 0f) 1f else scale / before
        offsetXPx = focusX - (focusX - offsetXPx) * k
        offsetYPx = focusY - (focusY - offsetYPx) * k
        clamp()
        invalidate()
    }

    override fun onSizeChanged(
        w: Int,
        h: Int,
        oldw: Int,
        oldh: Int,
    ) = clamp()

    override fun onDraw(canvas: Canvas) {
        canvas.drawColor(SURROUND_ARGB)
        val page = specimen ?: return
        canvas.withTranslation(offsetXPx, offsetYPx) { page.draw(this, scale) }
    }

    @SuppressLint("ClickableViewAccessibility") // spike: drag to pan only, no click action
    override fun onTouchEvent(event: MotionEvent): Boolean {
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                Unit
            }

            MotionEvent.ACTION_MOVE -> {
                offsetXPx += event.x - lastX
                offsetYPx += event.y - lastY
                clamp()
                invalidate()
            }
        }
        lastX = event.x
        lastY = event.y
        return true
    }

    private fun rebuild() {
        build?.cancel()
        layoutMs = null
        val next = method
        build =
            scope.launch {
                val startNs = SystemClock.elapsedRealtimeNanos()
                specimen = withContext(dispatchers.text) { FontSpecimen(layouter, FontRegistry.families, next, compact = false) }
                layoutMs = (SystemClock.elapsedRealtimeNanos() - startNs) / NS_PER_MS
                clamp()
                invalidate()
            }
    }

    /** Centers a page narrower than the view; otherwise keeps at least half a screen of page visible. */
    private fun clamp() {
        val contentW = FontSpecimen.WIDTH_PT * scale
        val contentH = (specimen?.heightPt ?: 0f) * scale
        offsetXPx = if (contentW <= width) (width - contentW) / 2f else offsetXPx.coerceIn(width / 2f - contentW, width / 2f)
        offsetYPx = offsetYPx.coerceIn(minOf(0f, height / 2f - contentH), height / 2f)
    }

    companion object {
        const val ROUTE = "spike-fonts"
        const val MIN_ZOOM = 0.25f
        const val MAX_ZOOM = 8f
        private const val SIDE_PADDING_DP = 24f
        private const val NS_PER_MS = 1_000_000.0
        private const val SURROUND_ARGB = 0xFFE9ECF1.toInt()
    }
}

package dev.folio.app.spikes

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import kotlinx.serialization.json.putJsonObject

/**
 * Spike P01-S7 accumulator: what the Focus Pen delivers to an app. Plain numbers in, JSON out, so
 * it is testable without MotionEvents. Deleted or promoted (StylusCapabilities, P03) by P01-T08.
 */
internal class StylusStats {
    /** Observed min..max of one axis; empty until the first value. */
    class AxisRange {
        var min = Float.POSITIVE_INFINITY
            private set
        var max = Float.NEGATIVE_INFINITY
            private set
        val seen: Boolean get() = min <= max

        fun add(value: Float) {
            if (value < min) min = value
            if (value > max) max = value
        }
    }

    val pressure = AxisRange()
    val tiltRad = AxisRange()
    val orientationRad = AxisRange()
    val distance = AxisRange()
    val toolTypes = IntArray(TOOL_TYPES)
    var contactEvents = 0
        private set
    var hoverEvents = 0
        private set
    var buttonStatesSeen = 0
        private set
    val buttonPresses = sortedMapOf<Int, Int>()
    val keyCodes = sortedMapOf<Int, Int>()
    var maxHistory = 0
        private set
    private var historyTotal = 0L
    private val intervalsUs = LongArray(MAX_INTERVALS)
    private var intervalCount = 0
    private var lastSampleNs = NO_SAMPLE

    /** One pointer sample of a stylus event; [hovering] for ACTION_HOVER_*, else contact. */
    @Suppress("LongParameterList") // one argument per MotionEvent axis keeps this free of android.* types
    fun onSample(
        toolType: Int,
        hovering: Boolean,
        pressure: Float,
        tiltRad: Float,
        orientationRad: Float,
        distance: Float,
        buttonState: Int,
    ) {
        if (toolType in toolTypes.indices) toolTypes[toolType]++
        if (hovering) hoverEvents++ else contactEvents++
        if (!hovering) this.pressure.add(pressure)
        this.tiltRad.add(tiltRad)
        this.orientationRad.add(orientationRad)
        this.distance.add(distance)
        buttonStatesSeen = buttonStatesSeen or buttonState
    }

    /** Batch size of one MotionEvent (historical samples). */
    fun onBatch(historySize: Int) {
        if (historySize > maxHistory) maxHistory = historySize
        historyTotal += historySize
    }

    /** Time of a contact sample (current or historical) in ns; consecutive samples give the rate. */
    fun onSampleTime(timeNs: Long) {
        if (lastSampleNs != NO_SAMPLE && timeNs > lastSampleNs) {
            intervalsUs[intervalCount % MAX_INTERVALS] = (timeNs - lastSampleNs) / NS_PER_US
            intervalCount++
        }
        lastSampleNs = timeNs
    }

    /** Pen lifted: the next sample starts a new interval chain. */
    fun onGestureEnd() {
        lastSampleNs = NO_SAMPLE
    }

    fun onButtonPress(actionButton: Int) {
        buttonPresses[actionButton] = (buttonPresses[actionButton] ?: 0) + 1
    }

    fun onKey(keyCode: Int) {
        keyCodes[keyCode] = (keyCodes[keyCode] ?: 0) + 1
    }

    /** Median time between contact samples, or null before two samples. */
    fun medianIntervalMs(): Double? {
        val n = minOf(intervalCount, MAX_INTERVALS)
        if (n == 0) return null
        val sorted = intervalsUs.copyOf(n).apply { sort() }
        return sorted[n / 2] / US_PER_MS
    }

    fun toJson(): JsonObject =
        buildJsonObject {
            put("contactEvents", contactEvents)
            put("hoverEvents", hoverEvents)
            putJsonObject("toolTypes") { toolTypes.forEachIndexed { type, count -> if (count > 0) put(type.toString(), count) } }
            putRange("pressure", pressure)
            putRange("tiltRad", tiltRad)
            putRange("orientationRad", orientationRad)
            putRange("distance", distance)
            put("buttonStatesSeen", buttonStatesSeen)
            putJsonObject("buttonPresses") { buttonPresses.forEach { (button, count) -> put(button.toString(), count) } }
            putJsonObject("keyCodes") { keyCodes.forEach { (code, count) -> put(code.toString(), count) } }
            put("maxHistory", maxHistory)
            put("historyTotal", historyTotal)
            val interval = medianIntervalMs()
            put("medianIntervalMs", interval)
            put("sampleRateHz", interval?.let { MS_PER_S / it })
        }

    private fun kotlinx.serialization.json.JsonObjectBuilder.putRange(
        name: String,
        range: AxisRange,
    ) {
        if (!range.seen) return
        putJsonObject(name) {
            put("min", range.min)
            put("max", range.max)
        }
    }

    private companion object {
        const val TOOL_TYPES = 5 // MotionEvent.TOOL_TYPE_UNKNOWN..TOOL_TYPE_PALM
        const val MAX_INTERVALS = 4096
        const val NO_SAMPLE = -1L
        const val NS_PER_US = 1_000L
        const val US_PER_MS = 1_000.0
        const val MS_PER_S = 1_000.0
    }
}

package dev.folio.core.text.spike

import android.graphics.Canvas
import android.graphics.Paint
import dev.folio.core.text.fonts.BundledFontFamily
import dev.folio.core.text.layout.BaselineMethod
import dev.folio.core.text.layout.GridParagraph
import dev.folio.core.text.layout.GridTextLayouter

/**
 * Spike P01-S3: every bundled font on college-ruled paper, one block per font. [compact] shows one
 * sample line per font (screenshot test); otherwise the first probe paragraph (`spike-fonts`).
 * Deleted or promoted by P01-T08.
 */
class FontSpecimen(
    layouter: GridTextLayouter,
    families: List<BundledFontFamily>,
    method: BaselineMethod,
    compact: Boolean,
) {
    private val blocks: List<GridParagraph>
    private val topsPt: FloatArray

    /** Page height in pt covering every block plus one rule of margin. */
    val heightPt: Float

    private val rule = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = RULE_ARGB.toInt() }
    private val margin = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = MARGIN_ARGB.toInt() }
    private val paper = Paint().apply { color = PAPER_ARGB.toInt() }

    init {
        val unit = BaselineProbe.UNIT_PT
        blocks =
            families.map { family ->
                val text = if (compact) "${family.name}: Hamburgefonstiv 0123 gjpqy" else "${family.name}. ${BaselineProbe.PARAGRAPHS[0]}"
                layouter.layout(text, family, unit, BaselineProbe.BODY_M_CAP, BaselineProbe.WIDTH_PT, method)
            }
        topsPt = FloatArray(blocks.size)
        var top = TOP_RULES * unit
        blocks.forEachIndexed { i, block ->
            topsPt[i] = top
            top += block.heightPt + if (compact) 0f else unit
        }
        heightPt = top + unit
    }

    /** Draws paper, rules, margin line and all blocks at [scale] px per pt with the page origin at 0,0. */
    fun draw(
        canvas: Canvas,
        scale: Float,
    ) {
        val unit = BaselineProbe.UNIT_PT
        val widthPx = WIDTH_PT * scale
        canvas.drawRect(0f, 0f, widthPx, heightPt * scale, paper)
        rule.strokeWidth = RULE_WIDTH_PT * scale
        margin.strokeWidth = RULE_WIDTH_PT * scale
        var y = unit
        while (y < heightPt) {
            canvas.drawLine(0f, y * scale, widthPx, y * scale, rule)
            y += unit
        }
        canvas.drawLine(MARGIN_PT * scale, 0f, MARGIN_PT * scale, heightPt * scale, margin)
        blocks.forEachIndexed { i, block -> block.draw(canvas, MARGIN_PT + TEXT_INSET_PT, topsPt[i], scale) }
    }

    companion object {
        const val WIDTH_PT = 595.28f
        private const val TOP_RULES = 2
        private const val MARGIN_PT = 25f * 72f / 25.4f
        private const val TEXT_INSET_PT = 2f * 72f / 25.4f
        private const val RULE_WIDTH_PT = 0.5f
        private const val RULE_ARGB = 0xFFC9D3E0
        private const val MARGIN_ARGB = 0xFFF2A6A6
        private const val PAPER_ARGB = 0xFFFFFFFF
    }
}

package dev.folio.core.text.spike

import dev.folio.core.text.fonts.BundledFontFamily
import dev.folio.core.text.fonts.FontMetricsCache
import dev.folio.core.text.layout.BaselineMethod
import dev.folio.core.text.layout.GridTextLayouter
import java.util.Locale
import kotlin.math.abs
import kotlin.math.max

/** Baseline and cap-height accuracy of one family laid out with one [BaselineMethod] (P01-S3). */
class BaselineProbeResult(
    val family: String,
    val method: BaselineMethod,
    val lines: Int,
    /** Largest |baseline - rule| over all lines, in pt. */
    val maxBaselineErrorPt: Float,
    /** |laid out cap height - target| at the reference size, in pt. */
    val capErrorPt: Float,
    val fontSizePt: Float,
    val capRatio: Float,
    /** Median layout time per paragraph. */
    val layoutMedianMs: Double,
) {
    /** Baseline error in screen px on the Pad 7 at [zoom] x fit-width. */
    fun maxBaselineErrorPx(zoom: Float): Float = maxBaselineErrorPt * zoom * BaselineProbe.PAD7_FIT_SCALE

    /** Cap-height error in screen px on the Pad 7 at fit-width. */
    val capErrorPx: Float get() = capErrorPt * BaselineProbe.PAD7_FIT_SCALE
}

/**
 * Spike P01-S3: lays out three paragraphs per font on a college-ruled grid (U = 7.1 mm, body M)
 * and measures how far each baseline lands from its rule. Shared by the Robolectric test, the
 * instrumented test and the `spike-fonts` debug route. Deleted or promoted by P01-T08.
 */
object BaselineProbe {
    /** College ruling, 7.1 mm (05-canvas-rendering.md#templates). */
    const val UNIT_PT = 7.1f * 72f / 25.4f

    /** Body M target cap height as a fraction of U (07-text-engine.md#font-normalization). */
    const val BODY_M_CAP = 0.45f

    /** Text column: A4 width minus the 25 mm margin line and 10 mm on the right. */
    const val WIDTH_PT = (210f - 25f - 10f) * 72f / 25.4f

    /** Fit-width px per pt on the Pad 7 in landscape: (3200 px - 48 dp at 2.75) / A4 width. */
    const val PAD7_FIT_SCALE = (3200f - 48f * 2.75f) / 595.28f

    /** Zoom levels (x fit-width) the invariant must hold at (07-text-engine.md#line-box). */
    val ZOOMS = floatArrayOf(1f, 2f, 4f)

    /** Allowed baseline error in screen px (ADR-008 decision rule). */
    const val MAX_ERROR_PX = 0.5f

    val PARAGRAPHS: List<String> =
        listOf(
            "Handwritten notes and typed text share one page. Every line of this paragraph must sit " +
                "exactly on a rule of the template, no matter which font is chosen or how far the page is zoomed.",
            "Numbers 0123456789, punctuation (a; b: c!) \"quotes\", accents: éèê àâ ü ö ß ñ ç, and " +
                "long words like Donaudampfschifffahrtsgesellschaft wrap without drifting off the grid.",
            "Short line.\nA line after a hard break keeps the pitch; so does the last line of the block, " +
                "which ends with descenders: gjpqy.",
        )

    private const val NS_PER_MS = 1_000_000.0

    /** Measures [family] with [method]; the block top sits on a rule, so line i belongs on rule i + 1. */
    fun run(
        layouter: GridTextLayouter,
        metrics: FontMetricsCache,
        family: BundledFontFamily,
        method: BaselineMethod,
    ): BaselineProbeResult {
        var lines = 0
        var maxError = 0f
        var fontSizePt = 0f
        val timesMs = DoubleArray(PARAGRAPHS.size)
        PARAGRAPHS.forEachIndexed { index, text ->
            val start = System.nanoTime()
            val block = layouter.layout(text, family, UNIT_PT, BODY_M_CAP, WIDTH_PT, method)
            timesMs[index] = (System.nanoTime() - start) / NS_PER_MS
            fontSizePt = block.fontSizePt
            for (line in 0 until block.lineCount) {
                maxError = max(maxError, abs(block.baselinePt(line) - (line + 1) * UNIT_PT))
            }
            lines += block.lineCount
        }
        val proportions = metrics.proportions(family)
        val paint = FontMetricsCache.measurePaint(metrics.typeface(family), fontSizePt * GridTextLayouter.REFERENCE_SCALE)
        val capPt = FontMetricsCache.capHeightPx(paint) / GridTextLayouter.REFERENCE_SCALE
        timesMs.sort()
        return BaselineProbeResult(
            family = family.name,
            method = method,
            lines = lines,
            maxBaselineErrorPt = maxError,
            capErrorPt = abs(capPt - BODY_M_CAP * UNIT_PT),
            fontSizePt = fontSizePt,
            capRatio = proportions.capRatio,
            layoutMedianMs = timesMs[timesMs.size / 2],
        )
    }

    /** A Markdown table of [results]: baseline error in px per zoom, cap error, size, layout time. */
    fun table(results: List<BaselineProbeResult>): String =
        buildString {
            appendLine(
                "| Font | Method | Lines | Max baseline error px z1 / z2 / z4 | Cap error px | Size pt | Cap ratio | Layout ms/para |",
            )
            appendLine("|---|---|---|---|---|---|---|---|")
            for (r in results) {
                val errors = ZOOMS.joinToString(" / ") { "%.3f".format(Locale.ROOT, r.maxBaselineErrorPx(it)) }
                appendLine(
                    "| ${r.family} | ${r.method} | ${r.lines} | $errors | ${"%.3f".format(Locale.ROOT,r.capErrorPx)} | " +
                        "${"%.2f".format(
                            Locale.ROOT,
                            r.fontSizePt,
                        )} | ${"%.3f".format(Locale.ROOT,r.capRatio)} | ${"%.2f".format(Locale.ROOT,r.layoutMedianMs)} |",
                )
            }
        }
}

